-- Import de 4305 prix depuis Prix_20261021_105312.csv.
-- Les separateurs de milliers '.' sont retires, comme dans format_utils.parse_nombre().
-- Les prix a zero sont conserves. Executer apres 02_articles_unites.sql.
BEGIN;
SET search_path TO public, pg_catalog;

DO $$
BEGIN
    IF to_regclass('public._ambanja_bazarbe_article_map') IS NULL THEN
        RAISE EXCEPTION 'Executer 02_articles_unites.sql avant les prix';
    END IF;
    IF (SELECT COUNT(*) FROM public._ambanja_bazarbe_article_map) <> 2331 THEN
        RAISE EXCEPTION 'Correspondance articles incomplete';
    END IF;
    IF (SELECT COUNT(*) FROM public.tb_unite) <> 4305 THEN
        RAISE EXCEPTION 'Nombre d unites inattendu avant import des prix';
    END IF;
    IF EXISTS (SELECT 1 FROM public.tb_prix) THEN
        RAISE EXCEPTION 'La table tb_prix doit etre vide avant cet import';
    END IF;
END $$;

